/* ============================================
   TABLE COMPONENT
   Data table with flexible cell content
   ============================================ */

.ds-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border-radius: var(--radius-200); /* 8px */

  /* Typography */
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-primary);
}

/* The plain table clips its own rounded corners. The bordered table does
   not: its wrapper is the scroll container and clips for it, which leaves
   the table itself free of overflow so sticky headers and pinned columns can
   stick to the scrolling wrapper. */
.ds-table:not(.ds-table--bordered) {
  overflow: hidden;
}

/* ============================================
   CAPTION
   ============================================ */

.ds-table__caption {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-secondary);
  text-align: left;
  caption-side: top;
  padding-bottom: var(--padding-200); /* 8px */
}


/* ============================================
   ROW
   ============================================ */

.ds-table__row {
  border-bottom: var(--border-025) solid var(--color-table-divider);
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   HEADER CELL
   ============================================ */

.ds-table__header-cell {
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  vertical-align: middle;

  /* paragraph-em (500 weight / label style) */
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-secondary);
  text-align: left;
}

/* ============================================
   DATA CELL
   ============================================ */

.ds-table__cell {
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  vertical-align: middle;
  color: var(--color-text-primary);
}

/* Inner wrapper ensures all cell content is perfectly vertically centred */
.ds-table__cell-content {
  display: flex;
  align-items: center;
  min-height: 0;
}

/* ============================================
   ROW HOVER (body rows only)
   ============================================ */

.ds-table__body .ds-table__row:hover {
  background-color: var(--color-table-row-hover-bg);
}

/* A row header is a <th scope="row"> for its semantics only: it is drawn as
   a data cell, without the browser's bold and centring. */
.ds-table__cell--row-header {
  font-weight: inherit;
  text-align: start;
}

/* ============================================
   STRIPED ROWS
   ============================================ */

.ds-table--striped .ds-table__body .ds-table__row:nth-child(even) {
  background-color: var(--color-table-row-stripe-bg);
}

.ds-table--striped .ds-table__body .ds-table__row:nth-child(even):hover {
  background-color: var(--color-table-row-hover-bg);
}

/* ============================================
   SIZE — DEFAULT (base styles apply)
   ============================================ */

.ds-table--default {
  /* Base padding & typography inherited from .ds-table */
}

/* ============================================
   BORDERED VARIANT
   Outer border box + tinted thead + divider row lines.
   Matches the table style used on markdown content pages.
   ============================================ */

/* The bordered table is a surface of its own: brighter than what it sits
   on in light, a little darker in dark, with an outline and a header band
   one step off the body. Its colours are the --color-table-* family, which
   every table reads. */
.ds-table__wrapper {
  overflow-x: auto;
  border: var(--border-025) solid var(--color-table-border);
  border-radius: var(--radius-300); /* 12px */
  background: var(--color-table-body-bg);
}

/* Columns never reflow on a phone: the wrapper scrolls instead
   (design.md's responsive contract). Natural column widths below the
   mobile breakpoint force the overflow the wrapper exists to catch —
   without this the table crushes to the viewport and cells clip. */
@media (max-width: 768px) {
  .ds-table__wrapper .ds-table {
    min-width: max-content;
  }
}

/* A bordered table's visible caption is drawn above the outline, where
   the plain table's sits: a <caption> would render inside the wrapper's
   border and scroll with it. The <caption> stays in the table, hidden, so
   the table and its scroll region keep their name. */
.ds-table__frame {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* When bordered, the table fills the wrapper — no radius needed on the table itself */
.ds-table--bordered {
  border-radius: 0;
}

/* Thead steps one notch off the body surface, so the header band reads as
   a header in both themes without a second border. */
.ds-table--bordered .ds-table__head {
  background: var(--color-table-header-bg);
}

/* Remove row-level border — border-collapse: separate ignores it */
.ds-table--bordered .ds-table__row {
  border-bottom: none;
}

/* Header cells: bottom divider */
.ds-table--bordered .ds-table__header-cell {
  border-bottom: var(--border-025) solid var(--color-table-divider);
}

/* Body cells: bottom divider */
.ds-table--bordered .ds-table__cell {
  border-bottom: var(--border-025) solid var(--color-table-divider);
}

/* Last body row: no bottom border (the wrapper border handles it) */
.ds-table--bordered .ds-table__body .ds-table__row:last-child .ds-table__cell {
  border-bottom: none;
}

/* Row hover on the bordered variant: the same table hover token as the
   plain table, a tint over whatever surface the body shows. */
.ds-table--bordered .ds-table__body .ds-table__row:hover {
  background-color: var(--color-table-row-hover-bg);
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-table--compact .ds-table__header-cell {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-table--compact .ds-table__cell {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

/* ============================================
   SCREEN-READER-ONLY
   Fallback text for header cells with no visible
   label (checkbox / actions columns) — an empty
   <th> is unannounced.
   ============================================ */

/* ============================================
   SELECTED ROW
   Last in the file and as specific as the striped
   hover rule, so the selected tint holds over
   hover, stripe and the bordered hover alike.
   ============================================ */
.ds-table .ds-table__body .ds-table__row.ds-table__row--selected:nth-child(n) {
  background-color: var(--color-table-row-selected-bg);
}

/* ============================================
   COLUMN DIVIDERS
   A vertical line between columns, beside the
   lines between rows: for dense numeric tables
   that read down as well as across.
   ============================================ */
.ds-table--column-dividers .ds-table__header-cell:not(:last-child),
.ds-table--column-dividers .ds-table__cell:not(:last-child) {
  border-inline-end: var(--border-025) solid var(--color-table-divider);
}

// No 'use client' directive: Table is purely presentational — no hooks, no event
// handlers — so it stays renderable from a React Server Component. The one
// measured part, the bordered wrapper's ScrollRegion, is a client boundary of
// its own.

import React from 'react';
import './Table.css';
import { ScrollRegion } from '../../behaviors/ScrollRegion';
import '../../behaviors/visually-hidden.css';

export interface TableColumn {
  /** Unique column identifier, used as the key into each row's cells */
  key: string;
  /** Header label displayed in the column header */
  header: React.ReactNode;
  /** Optional column width (CSS value like '200px', '30%', 'auto') */
  width?: string;
  /** Text alignment for cells in this column */
  align?: 'left' | 'center' | 'right';
  /** The column's current sort, set as `aria-sort` on its header so a screen reader announces it while reading the column. Leave unset on unsorted columns. */
  sort?: 'ascending' | 'descending';
  /** Whether this column names each row. Its cells render as row headers (`<th scope="row">`), so moving along a row announces which record it is. */
  rowHeader?: boolean;
}

export interface TableRow {
  /** Unique row identifier */
  id: string;
  /** Cell values keyed by column key — each accepts any React node */
  cells: Record<string, React.ReactNode>;
  /** Whether the row is selected, drawn with the table's selected-row tint. */
  selected?: boolean;
}

/** Props owned by Table itself — everything else falls through to the <table>. */
type TableOwnProps = {
  /** Column definitions */
  columns: TableColumn[];
  /** Row data */
  rows: TableRow[];
  /** Visual size */
  size?: 'default' | 'compact';
  /** Alternating row background colours */
  striped?: boolean;
  /**
   * Adds an outer border + border-radius container, a tinted thead background,
   * and `--color-divider` row lines — matching the bordered table style used on
   * markdown content pages.
   */
  bordered?: boolean;
  /** Draws a vertical line between columns, as well as the lines between rows. */
  columnDividers?: boolean;
  /** Accessible caption for the table */
  caption?: string;
  /** Whether to visually hide the caption (still available to screen readers) */
  captionHidden?: boolean;
  /** Additional CSS classes */
  className?: string;
};

export interface TableProps
  extends TableOwnProps,
    Omit<React.ComponentPropsWithoutRef<'table'>, keyof TableOwnProps> {}

/**
 * Table component from Figma design system.
 * Data table with flexible cell content — supports text, icons,
 * inputs, buttons, and any other React nodes inside cells.
 *
 * Forwards a ref to the `<table>` element and spreads unrecognised props onto
 * it. When `bordered`, the table is wrapped in a container div — the ref and
 * spread props still target the inner `<table>`.
 */
export const Table = React.forwardRef<HTMLTableElement, TableProps>(
  (
    {
      columns,
      rows,
      size = 'default',
      striped = false,
      bordered = false,
      columnDividers = false,
      caption,
      captionHidden = false,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-table';

    const classes = [
      baseClass,
      `${baseClass}--${size}`,
      striped ? `${baseClass}--striped` : '',
      bordered ? `${baseClass}--bordered` : '',
      columnDividers ? `${baseClass}--column-dividers` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    // A bordered table draws its visible caption outside the outline (see
    // the frame rule in Table.css), so the <caption> itself is hidden.
    const outsideCaption = bordered && caption && !captionHidden;

    const table = (
      <table {...rest} ref={ref} className={classes}>
        {caption && (
          <caption
            className={
              captionHidden || outsideCaption ? `${baseClass}__caption ds-visually-hidden` : `${baseClass}__caption`
            }
          >
            {caption}
          </caption>
        )}

        <thead className={`${baseClass}__head`}>
          <tr className={`${baseClass}__row ${baseClass}__row--header`}>
            {columns.map((col) => (
              <th
                key={col.key}
                className={`${baseClass}__header-cell`}
                scope="col"
                aria-sort={col.sort}
                style={{
                  width: col.width,
                  textAlign: col.align || 'left',
                }}
              >
                {/* An empty header cell is unannounced — fall back to the
                    column key so the column is still identifiable. */}
                {col.header || <span className="ds-visually-hidden">{col.key}</span>}
              </th>
            ))}
          </tr>
        </thead>

        <tbody className={`${baseClass}__body`}>
          {rows.map((row) => (
            <tr
              key={row.id}
              className={row.selected ? `${baseClass}__row ${baseClass}__row--selected` : `${baseClass}__row`}
            >
              {columns.map((col) => {
                const content = (
                  <div
                    className={`${baseClass}__cell-content`}
                    style={{
                      justifyContent:
                        col.align === 'center'
                          ? 'center'
                          : col.align === 'right'
                            ? 'flex-end'
                            : 'flex-start',
                    }}
                  >
                    {row.cells[col.key]}
                  </div>
                );
                return col.rowHeader ? (
                  <th key={col.key} className={`${baseClass}__cell ${baseClass}__cell--row-header`} scope="row">
                    {content}
                  </th>
                ) : (
                  <td key={col.key} className={`${baseClass}__cell`}>
                    {content}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    );

    // The bordered wrapper is the table's scroll container: a named,
    // focusable region while it overflows, a plain div while it fits.
    if (bordered) {
      const region = <ScrollRegion className={`${baseClass}__wrapper`}>{table}</ScrollRegion>;
      if (!outsideCaption) return region;
      return (
        <div className={`${baseClass}__frame`}>
          <div className={`${baseClass}__caption`} aria-hidden="true">
            {caption}
          </div>
          {region}
        </div>
      );
    }

    return table;
  },
);

Table.displayName = 'Table';
